        # try to match each task in p to distinct workers
        def match(t_idx, used_workers):
            if t_idx == len(p):
                return True
            for w in workers:
                if w not in used_workers and (p[t_idx], w) in valid:
                    used_workers.add(w)
                    if match(t_idx + 1, used_workers):
                        return True
                    used_workers.remove(w)
            return False
        if match(0, set()):
            max_tasks = max(max_tasks, r)
result = max_tasks

